// NPC Constructor Puertas de Madera (OOP Standard + Detección de Puerta Madera)
(async function() {
  if (!game.defineStandardAgent) {
    try {
      var res = await fetch('/api/snippets/base-npc-skills');
      var snip = await res.json();
      if (snip && snip.code) (new Function(snip.code))();
    } catch(e) { console.error('Error cargando base-npc-skills:', e); }
  }

  await game.addMaterial('lava');
  await game.addMaterial('obsidian');
  await game.addMaterial('obsidiana');
  await game.addMaterial('madera');
  await game.addMaterial('tejado');
  await game.addMaterial('yellow_concrete');
  await game.addMaterial('red_concrete');

  game.defineStandardAgent({
    id: 'constructor_puertas_madera',
    name: 'Constructor Puertas de Madera',
    margin: 1,
    passengers: true,
    tickMs: 200,
    skills: {
      puertasMadera: true,
      saltoTactico: false
    }
  });
})();
